// ───────────────────────────── time budget (hard ~8 s per search) ─────────────────────────────
const BUDGET_MS = 8000;

/** Resolves with the promise's value, or with `fallback` once `ms` runs out (or on error). Never rejects. */
function within<T>(p: Promise<T>, ms: number, fallback: T): Promise<T> {
	if (ms <= 0) return Promise.resolve(fallback);
	return new Promise((resolve) => {
		const t = setTimeout(() => resolve(fallback), ms);
		p.then(
			(v) => {
				clearTimeout(t);
				resolve(v);
			},
			() => {
				clearTimeout(t);
				resolve(fallback);
			},
		);
	});
}

/** First non-null result; null once every promise has come back empty. */
function firstGood<T>(ps: Promise<T | null>[]): Promise<T | null> {
	return new Promise((resolve) => {
		let pending = ps.length;
		if (!pending) resolve(null);
		for (const p of ps)
			p.then(
				(v) => {
					if (v !== null && v !== undefined) resolve(v);
					else if (--pending === 0) resolve(null);
				},
				() => {
					if (--pending === 0) resolve(null);
				},
			);
	});
}

/** Resolves after `ms`, or earlier as soon as `prev` comes back empty (so the next source starts right away). */
function after(prev: Promise<unknown>, ms: number): Promise<void> {
	return new Promise((resolve) => {
		const t = setTimeout(resolve, ms);
		prev.then(
			(v) => {
				if (v === null || v === undefined) {
					clearTimeout(t);
					resolve();
				}
			},
			() => {
				clearTimeout(t);
				resolve();
			},
		);
	});
}

